@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap');
:root{--ink:#e7ebd8;--muted:#a3af98;--bg:#141f19;--panel:#1d2b22;--line:#344438;--gold:#e7bd72;--green:#a4bf86;--mint:#d0dfb6}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% -20%,#314136 0,#19271f 55%,#111b16 100%);color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;display:flex;justify-content:center;align-items:center;padding:22px}.app-shell{width:min(1200px,100%);background:#19251d;border:1px solid #405144;box-shadow:0 28px 90px #070d09b8;border-radius:12px;overflow:hidden}.topbar{height:66px;background:#1c2a21;border-bottom:1px solid #35443a;display:flex;align-items:center;padding:0 23px;gap:12px}.brand-mark{font-size:26px;color:#bad291;width:33px;text-align:center;text-shadow:0 0 15px #9bbf65}.brand{display:flex;flex-direction:column;gap:1px}.brand strong{font-family:'Fraunces',serif;font-size:15px;letter-spacing:2.5px;color:#edf0dc}.brand span{font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#94a58e}.top-spacer{flex:1}.weather-pill{border:1px solid #405344;border-radius:20px;padding:7px 12px;color:#c5d5a5;font-size:12px;display:flex;gap:8px;align-items:center;background:#243329}.weather-pill span:first-child{color:#f2c77f;font-size:16px}.icon-btn{border:1px solid #405344;background:#243329;border-radius:8px;color:#c6d5ae;width:34px;height:34px;font-size:16px;cursor:pointer}.icon-btn:hover,.calendar-btn:hover{background:#34493a}.layout{display:grid;grid-template-columns:minmax(0,1fr) 292px;gap:0;min-height:560px}.play-column{padding:21px 20px 14px;min-width:0}.scene-wrap{position:relative;background:#506847;border:1px solid #627457;border-radius:8px;overflow:hidden;box-shadow:0 12px 30px #0e1710a6;aspect-ratio:8/5}.scene-wrap canvas{display:block;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#07150c35 0%,transparent 20%,transparent 78%,#08150d58 100%)}.location-tag{position:absolute;left:15px;top:14px;padding:7px 11px;background:#17241ddd;border:1px solid #a1b38a4a;border-radius:4px;color:#edf1d9;font:10px 'DM Mono',monospace;letter-spacing:.7px;box-shadow:0 2px 8px #1118}.location-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c9dc91;margin-right:8px;box-shadow:0 0 6px #cfed80}.scene-hint{position:absolute;right:13px;top:14px;background:#18251bd9;border:1px solid #a1b38a35;color:#cad4b8;padding:7px 10px;border-radius:4px;font:10px 'DM Mono',monospace}.scene-hint i{color:#d6b66e;font-style:normal;padding:0 4px}.toast{position:absolute;top:51px;left:50%;transform:translate(-50%,-8px);padding:9px 16px;border:1px solid #e8d08c88;background:#283728ec;color:#f8e9ba;border-radius:4px;font-size:12px;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap;z-index:3}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom-bar{display:flex;align-items:center;padding:14px 2px 9px;gap:17px;border-bottom:1px solid #344237}.tool-label{width:105px;display:flex;flex-direction:column;gap:4px}.tiny-label{font:8px 'DM Mono',monospace;color:#849682;letter-spacing:1px}.tool-label strong{font-size:12px;color:#e3e8d3}.hotbar{display:flex;gap:5px}.slot{width:42px;height:42px;background:#233229;border:1px solid #52634e;border-radius:5px;position:relative;display:grid;place-items:center;cursor:pointer;transition:.12s}.slot:hover{background:#304433}.slot.selected{border:2px solid #e3c37e;box-shadow:0 0 0 2px #e3c37e22,inset 0 0 14px #dfbe6e20}.slot .slot-key{position:absolute;left:4px;top:2px;font:8px 'DM Mono',monospace;color:#9eaa8e}.slot .slot-icon{font-size:20px;filter:drop-shadow(1px 2px 0 #1118)}.slot .slot-count{position:absolute;bottom:2px;right:4px;color:#f1e7c2;font:9px 'DM Mono',monospace;text-shadow:1px 1px #111}.energy-wrap{margin-left:auto;min-width:110px}.energy-label{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;color:#a8ba9b;margin-bottom:6px}.energy-label b{color:#d5dcbd;font-weight:400}.energy-track{height:7px;background:#111b15;border:1px solid #435344;border-radius:8px;overflow:hidden}.energy-track i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#83ae73,#c5d58b);border-radius:8px;transition:width .25s}.help-row{display:flex;gap:20px;padding:11px 1px 0;color:#849382;font:9px 'DM Mono',monospace}.help-row kbd{font:9px 'DM Mono',monospace;color:#d1d8bd;background:#29372c;border:1px solid #495848;padding:2px 5px;border-radius:3px;margin-right:4px}.side-panel{padding:22px 18px 14px;border-left:1px solid #344439;background:linear-gradient(160deg,#202e25,#1a271f 80%);display:flex;flex-direction:column}.day-card{display:flex;justify-content:space-between;align-items:center;padding-bottom:16px;border-bottom:1px solid #3a493d}.eyebrow{font:9px 'DM Mono',monospace;color:#b1bf91;letter-spacing:1.4px}.day-title{font:24px 'Fraunces',serif;color:#f1f0dc;margin-top:3px}.clock{display:flex;align-items:center;gap:6px;color:#d9c690}.clock strong{font:11px 'DM Mono',monospace;font-weight:400}.sun-symbol{font-size:20px;color:#e8c67a}.wallet-row{height:68px;display:flex;align-items:center;gap:11px;border-bottom:1px solid #3a493d}.wallet-icon{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#51442c;color:#f1d491;font-size:17px;border:1px solid #8e7541}.wallet-row>div:nth-child(2){display:flex;flex-direction:column;gap:2px}.wallet-row small{font:8px 'DM Mono',monospace;color:#96a28b;letter-spacing:1px}.wallet-row strong{font:17px 'DM Mono',monospace;color:#eed58e}.wallet-row em{font-size:10px;font-style:normal;color:#a9b394}.calendar-btn{margin-left:auto;width:31px;height:31px;background:#29392e;border:1px solid #495849;border-radius:5px;color:#c6d2b2;font-size:17px;cursor:pointer}.panel-tabs{display:grid;grid-template-columns:repeat(3,1fr);margin:16px 0 11px;border-bottom:1px solid #3b4a3e}.tab{background:none;border:0;color:#829281;padding:0 0 9px;font:9px 'DM Mono',monospace;letter-spacing:.9px;cursor:pointer;position:relative}.tab.active{color:#e0c782}.tab.active:after{content:'';position:absolute;bottom:-1px;left:20%;right:20%;height:2px;background:#d7bd77}.tab-content{flex:1;min-height:300px}.section-title{font:15px 'Fraunces',serif;color:#e4e9d4;margin:3px 0 10px}.quest-card{padding:11px 11px 10px;border:1px solid #455542;background:#27372b;border-radius:5px;margin-bottom:10px}.quest-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.quest-name{font-size:11px;color:#e6e9d6;font-weight:600}.quest-tag{font:8px 'DM Mono',monospace;color:#e3cc8b;background:#4b442f;padding:3px 5px;border-radius:3px}.quest-card p{color:#adb9a2;font-size:10px;line-height:1.5;margin:0 0 9px}.progress-track{height:4px;background:#17231b;border-radius:3px;overflow:hidden}.progress-track i{display:block;height:100%;background:#a9c887}.objective{font:9px 'DM Mono',monospace;color:#9bab8e;margin-top:6px}.mini-heading{font:9px 'DM Mono',monospace;color:#92a188;letter-spacing:1px;margin:17px 0 8px}.weather-note{background:#243329;border-left:2px solid #c5b277;padding:9px 10px;color:#bdc9b0;font-size:10px;line-height:1.55}.weather-note b{color:#e1d09e;font-weight:600}.people-row{display:flex;align-items:center;gap:9px;padding:9px 0;border-bottom:1px solid #344337}.portrait{width:34px;height:34px;border:1px solid #6b7151;border-radius:5px;background:#4d6047;display:grid;place-items:center;font-size:20px}.person-info{flex:1}.person-info b{display:block;color:#e0e6d1;font-size:11px}.person-info span{font:9px 'DM Mono',monospace;color:#91a08b}.heart-meter{color:#d99087;font-size:10px;letter-spacing:1px}.craft-item{display:flex;align-items:center;gap:9px;padding:9px;border:1px solid #3d4c3f;background:#243329;border-radius:5px;margin-bottom:7px}.craft-icon{font-size:20px}.craft-copy{flex:1}.craft-copy b{font-size:10px;color:#e5e9d8;display:block}.craft-copy span{font-size:9px;color:#96a38e}.craft-item button{background:#516946;border:0;border-radius:4px;color:#e9f0d7;font:9px 'DM Mono',monospace;padding:6px 8px;cursor:pointer}.craft-item button:disabled{opacity:.35;cursor:not-allowed}.side-footer{border-top:1px solid #354439;padding-top:12px;margin-top:10px;display:flex;gap:7px;align-items:center;color:#8d9c89;font:9px 'DM Mono',monospace}.save-dot{width:6px;height:6px;background:#9fc37e;border-radius:50%;box-shadow:0 0 6px #99c779}.footer{height:37px;border-top:1px solid #354339;padding:0 21px;display:flex;justify-content:space-between;align-items:center;color:#83917e;font:9px 'DM Mono',monospace;letter-spacing:.3px}.footer span:first-child{color:#b4c39d}.modal-backdrop{position:fixed;inset:0;background:#0b130ed9;display:grid;place-items:center;padding:20px;z-index:20}.modal-backdrop.hidden{display:none}.modal-card{width:min(480px,100%);max-height:85vh;overflow:auto;background:#202e24;border:1px solid #596b52;border-radius:9px;box-shadow:0 25px 80px #000b;padding:21px}.modal-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #425142;padding-bottom:12px;margin-bottom:14px}.modal-head h2{font:22px 'Fraunces',serif;margin:0;color:#edf0dc}.close-btn{border:1px solid #4b5c4c;background:#2c3b30;color:#d6dfc4;border-radius:4px;width:28px;height:28px;cursor:pointer}.modal-body{color:#bac6ae;font-size:12px;line-height:1.65}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:12px 0}.inventory-cell{border:1px solid #465647;background:#29382d;border-radius:5px;padding:10px 6px;text-align:center;min-height:74px}.inventory-cell i{display:block;font-style:normal;font-size:21px}.inventory-cell b{display:block;font:9px 'DM Mono',monospace;color:#d9e0ca;margin-top:4px}.modal-buttons{display:flex;gap:8px;margin-top:14px}.modal-buttons button,.action-button{background:#819b65;border:0;border-radius:4px;padding:9px 13px;color:#142017;font:10px 'DM Mono',monospace;cursor:pointer}.modal-buttons button.secondary{background:#354638;color:#d8e0cd;border:1px solid #566653}.modal-buttons button:disabled{opacity:.4}.dialogue-name{font:10px 'DM Mono',monospace;color:#e5c984;letter-spacing:1px;margin-bottom:8px}.dialogue-text{font:15px 'Fraunces',serif;color:#e5ead6;line-height:1.5}.choice-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}.choice-row button{background:#344637;border:1px solid #566951;color:#dce5ce;padding:8px 11px;border-radius:4px;font-size:10px;cursor:pointer}.mobile-controls{display:none}
@media(max-width:850px){body{padding:0;align-items:flex-start}.app-shell{border-radius:0;border-left:0;border-right:0;min-height:100vh}.layout{grid-template-columns:minmax(0,1fr) 260px}.play-column{padding:15px 13px}.side-panel{padding:18px 14px}.slot{width:37px;height:39px}.bottom-bar{gap:10px}.tool-label{width:85px}.help-row{gap:10px;font-size:8px}}
@media(max-width:680px){body{padding:0}.topbar{height:54px;padding:0 14px}.weather-pill{padding:6px 9px;font-size:10px}.layout{display:flex;flex-direction:column}.play-column{padding:11px 10px 9px}.scene-wrap{aspect-ratio:8/5}.scene-hint{font-size:8px;right:8px;top:9px;padding:5px 7px}.location-tag{left:8px;top:9px;padding:5px 7px;font-size:8px}.bottom-bar{padding:9px 0 7px;gap:7px;flex-wrap:wrap}.tool-label{width:75px}.tool-label strong{font-size:10px}.tiny-label{font-size:7px}.slot{width:37px;height:37px}.slot .slot-icon{font-size:18px}.energy-wrap{min-width:85px;flex:1}.help-row{display:none}.side-panel{border-left:0;border-top:1px solid #3b4a3d;padding:13px 15px 10px}.day-card{padding-bottom:10px}.day-title{font-size:21px}.wallet-row{height:56px}.panel-tabs{margin:12px 0 9px}.tab-content{min-height:0}.side-footer{margin-top:7px}.footer{height:32px;padding:0 12px}.mobile-controls{position:absolute;left:12px;bottom:12px;display:flex;align-items:flex-end;gap:12px;opacity:.88}.mobile-controls>div{display:grid;grid-template-columns:repeat(3,37px);grid-template-rows:repeat(2,34px);gap:3px}.mobile-controls>div button{width:37px;height:34px}.mobile-controls>div button[data-move=up]{grid-column:2}.mobile-controls>div button[data-move=left]{grid-column:1;grid-row:2}.mobile-controls>div button[data-move=down]{grid-column:2;grid-row:2}.mobile-controls>div button[data-move=right]{grid-column:3;grid-row:2}.mobile-controls button{border:1px solid #d5d9bb78;border-radius:6px;background:#1b2b20bd;color:#f1f1dc;text-shadow:0 1px #111;font-size:12px;touch-action:none}.mobile-controls .mobile-action{width:55px;height:43px;background:#657f4ccc;font:9px 'DM Mono',monospace;margin-bottom:2px}.toast{top:43px;font-size:10px}.modal-card{padding:16px}.footer span:last-child{font-size:8px}}

(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=70,H=45,T=16,keys={},worldSeed=1947;let activeTab='journal',modalOpen=false,toastTimer,toastQueue=[],lastTime=0,anim=0;
const seasons=['Spring','Summer','Autumn','Winter'],weatherNames=['Clear skies','Soft rain','Cloudy'];
const state={px:15.5,py:15.5,face:'down',moving:false,day:1,season:0,year:1,time:360,gold:240,energy:100,maxEnergy:100,weather:0,tool:0,inventory:{Turnip Seeds:5,Carrot:0,Turnip:0,Wood:8,Stone:4,Fiber:0,Wildflower:0,Carp:0,Sunfish:0,Ore:0,Milk:0,Egg:0,Fish:0},crops:{},tilled:{},watered:{},friendship:{Mara:0,Theo:0,Lina:0},animal:{coop:false,barn:false},chests:[],unlocked:{forest:false,beach:false,mine:false},story:0,quests:{turnips:0},paused:false};
const tools=[{name:'Watering Can',icon:'♧'},{name:'Hoe',icon:'⚒'},{name:'Axe',icon:'🪓'},{name:'Pickaxe',icon:'⛏'}];
const crops={Turnip:{days:3,season:0,sell:42,icon:'🫜',seed:'Turnip Seeds'},Carrot:{days:4,season:0,sell:65,icon:'🥕',seed:'Carrot Seeds'},Tomato:{days:5,season:1,sell:95,icon:'🍅',seed:'Tomato Seeds'},Pumpkin:{days:7,season:2,sell:160,icon:'🎃',seed:'Pumpkin Seeds'}};
const npcs=[{name:'Mara',x:35,y:13,icon:'🧑🏽‍🌾',role:'The village gardener',story:'Mara has kept the village gardens blooming for as long as anyone can remember. She knows the valley’s old paths by heart.'},{name:'Theo',x:39,y:17,icon:'🧔🏻',role:'The patient fisher',story:'Theo spends quiet mornings by the river. He swears the water has been carrying strange little messages downstream.'},{name:'Lina',x:33,y:20,icon:'👩🏻‍🔬',role:'The curious stargazer',story:'Lina maps the night sky from her little observatory. Lately, a new constellation has appeared above the western ridge.'}];
const seedHash=(x,y)=>{let n=Math.imul(x+worldSeed,374761393)+Math.imul(y+9127,668265263);n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967295};
function zone(x,y){if(x>=54&&y>=7&&y<=17)return'Moonstone Mine';if(x>=47&&y>=12&&y<=28)return'Glasswater Beach';if(x>=29&&x<=44&&y>=8&&y<=24)return'Fernhollow Village';if(x>=8&&x<=26&&y>=9&&y<=22)return'Mosslight Farm';if(x<8||y<7||y>25||x>44)return'Whisperwood';return'Willowpath';}
function tile(x,y){if(x<0||y<0||x>=W||y>=H)return'water';let z=zone(x,y);if(z==='Glasswater Beach')return y>20?'sand':(y>16?'shore':'water');if(z==='Moonstone Mine')return'rock';if(z==='Fernhollow Village'){if(x===29||x===30||y===15||y===16)return'path';return seedHash(x,y)>.88?'flower':'grass'}if(z==='Mosslight Farm'){if(x===8||y===9||x===26||y===22)return'fence';if(x>=12&&x<=19&&y>=12&&y<=18)return'dirt';if((x===21&&y===12)||(x===22&&y===12)||(x===22&&y===13))return'house';if(x===24&&y>=15&&y<=17)return'path';if((x===10&&y===17)||(x===11&&y===17))return'rock';return seedHash(x,y)>.94?'flower':'grass'}if((x===28||x===29)&&y>13&&y<20)return'path';if(seedHash(x,y)>.72)return'tree';if(seedHash(x+4,y-8)>.965)return'rock';return'grass'}
function blocked(x,y){let t=tile(Math.floor(x),Math.floor(y));return ['water','tree','house','fence','rock'].includes(t)||(t==='shore'&&zone(Math.floor(x),Math.floor(y))!=='Glasswater Beach')}
function facingTile(){let d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[state.face];return[Math.floor(state.px)+d[0],Math.floor(state.py)+d[1]]}
const cropKey=(x,y)=>`${x},${y}`;function cropAt(x,y){return state.crops[cropKey(x,y)]}
function addItem(name,n=1){state.inventory[name]=(state.inventory[name]||0)+n;renderUI();save()}
function spendItem(name,n=1){if((state.inventory[name]||0)<n)return false;state.inventory[name]-=n;return true}
function say(text){toastQueue.push(text);if(!document.getElementById('toast').classList.contains('show'))showNextToast()}
function showNextToast(){let el=document.getElementById('toast');if(!toastQueue.length){el.classList.remove('show');return}el.textContent=toastQueue.shift();el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.classList.remove('show');setTimeout(showNextToast,250)},2200)}
function useTool(){if(modalOpen)return;let [x,y]=facingTile(),k=cropKey(x,y),t=tile(x,y);if(state.energy<3){say('You are too tired. Rest at home to recover.');return}if(state.tool===0){if(state.crops[k]){say('Your crop is already growing.');return}if(state.tilled[k]){state.watered[k]=state.day;state.energy-=2;say('The soil drinks in the water.');}else if(t==='water'||t==='shore'){fishing();return}else{say('The watering can needs a tilled patch.');return}}
if(state.tool===1){if(t==='grass'||t==='flower'||t==='path'){if(!spendItem('Turnip Seeds')){if(!spendItem('Carrot Seeds')){say('No seeds in your bag. Visit Mara for seeds.');return}state.crops[k]={type:'Carrot',age:0};}else state.crops[k]={type:'Turnip',age:0};state.tilled[k]=true;state.watered[k]=state.day;state.energy-=3;say('A tiny seed settles into the earth.');}}
if(state.tool===2){if(t==='tree'){addItem('Wood',3);state.energy-=4;say('You gathered 3 wood.');}else if(t==='flower'){addItem('Fiber',1);state.energy-=2;say('A little fiber for crafting.');}else{say('There is nothing to chop here.');return}}
if(state.tool===3){if(t==='rock'||t==='rockMine'){addItem('Stone',2);if(Math.random()<.35)addItem('Ore',1);state.energy-=4;say('You mined a small deposit.');}else if(zone(x,y)==='Moonstone Mine'){addItem('Ore',1);state.energy-=4;say('A glimmer of moonstone ore!');}else{say('No stone within reach.');return}}
updateHud()}
function interact(){if(modalOpen){closeModal();return}let [x,y]=facingTile(),n=npcs.find(p=>Math.abs(p.x-x)<2&&Math.abs(p.y-y)<2);if(n){talk(n);return}let z=zone(x,y);if(z==='Moonstone Mine'){state.unlocked.mine=true;openMine();return}if(z==='Glasswater Beach'){say('Glasswater shimmers in the late light. Cast a line with your can.');return}if(tile(x,y)==='house'){openHouse();return}if(tile(x,y)==='dirt'&&cropAt(x,y)){let c=cropAt(x,y),def=crops[c.type];if(c.age>=def.days){delete state.crops[cropKey(x,y)];delete state.tilled[cropKey(x,y)];addItem(c.type);state.quests.turnips++;say(`Harvested ${c.type}!`);return}say(`${c.type} · ${Math.max(0,def.days-c.age)} day(s) to harvest`);return}if(Math.floor(state.px)>21&&Math.floor(state.px)<26&&Math.floor(state.py)>15&&Math.floor(state.py)<19){openHouse();return}if(z==='Fernhollow Village'){openMarket();return}let dist=Math.hypot(state.px-35,state.py-13);if(dist<3){talk(npcs[0]);return}say('The valley is quiet. Try the village path to meet someone.')}
function fishing(){let z=zone(...facingTile());if(!['Glasswater Beach','Moonstone Mine'].includes(z)&&tile(...facingTile())!=='water'){say('Find a river or the sea to fish.');return}if(state.energy<8){say('You need a little more energy to fish.');return}state.energy-=8;let kind=Math.random();let fish=(z==='Glasswater Beach')?(kind>.7?'Sunfish':'Carp'):(kind>.72?'Sunfish':'Carp');addItem(fish);say(`A ${fish} bites! You reel it in.`);updateHud()}
function talk(n){let f=state.friendship[n.name]||0;modal(`<div class="dialogue-name">${n.name.toUpperCase()} · ${n.role}</div><div class="dialogue-text">${f===0?`“Oh, hello! You must be the new farmer. I’m ${n.name}. The valley feels a little brighter with someone new around.”`:f<3?`“Good to see you again. ${n.story}`:`“I’m glad you found your way here. I have a feeling this valley has more to tell us yet.”`}</div><div class="choice-row"><button data-choice="chat">Ask about the valley</button><button data-choice="gift">Offer a gift</button><button data-choice="bye">Say goodbye</button></div>`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='chat'){state.friendship[n.name]=Math.min(10,f+1);state.story=Math.max(state.story,1);closeModal();say(`${n.name} smiles. Friendship +1 ♡`);renderUI();save()}else if(b.dataset.choice==='gift'){gift(n)}else closeModal()})}
function gift(n){let giftName=Object.keys(state.inventory).find(k=>state.inventory[k]>0&&['Wildflower','Turnip','Carrot','Carp','Sunfish','Milk','Egg'].includes(k));if(!giftName){say('You do not have a gift to share yet.');return}spendItem(giftName);state.friendship[n.name]=Math.min(10,(state.friendship[n.name]||0)+2);closeModal();say(`${n.name} loves your ${giftName.toLowerCase()}! Friendship +2 ♡`);renderUI();save()}
function openMarket(){modal(`<div class="modal-head"><h2>Mara’s seed cart</h2><button class="close-btn" data-close>×</button></div><div class="modal-body">Fresh seeds for the new season. Pick something to grow in your little patch.</div><div class="craft-item"><span class="craft-icon">🫜</span><div class="craft-copy"><b>Turnip Seeds</b><span>Spring · 3 days · 20g</span></div><button data-buy="Turnip Seeds" data-cost="20">BUY</button></div><div class="craft-item"><span class="craft-icon">🥕</span><div class="craft-copy"><b>Carrot Seeds</b><span>Spring · 4 days · 32g</span></div><button data-buy="Carrot Seeds" data-cost="32">BUY</button></div><div class="craft-item"><span class="craft-icon">🍅</span><div class="craft-copy"><b>Tomato Seeds</b><span>Summer · 5 days · 48g</span></div><button data-buy="Tomato Seeds" data-cost="48">BUY</button></div>`);bindModal();document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let cost=+b.dataset.cost;if(state.gold<cost){say('Not enough gold yet.');return}state.gold-=cost;addItem(b.dataset.buy);say(`${b.dataset.buy} added to your bag.`);renderUI();save()})}
function openHouse(){modal(`<div class="modal-head"><h2>Your little farmhouse</h2><button class="close-btn" data-close>×</button></div><div class="modal-body"><p>The old windows catch the last of the afternoon sun. It’s simple, but it’s yours.</p><div class="quest-card"><div class="quest-top"><span class="quest-name">A Place to Begin</span><span class="quest-tag">HOME</span></div><p>Home is where a new story takes root. Rest here to welcome the next morning.</p></div><button class="action-button" id="sleepBtn">Rest until morning</button> <button class="action-button" id="upgradeBtn">House upgrade · 500g</button><p>Craft a chest from 12 wood and 4 stone to store your finds.</p></div>`);bindModal();document.getElementById('sleepBtn').onclick=()=>{closeModal();nextDay()};document.getElementById('upgradeBtn').onclick=()=>{if(state.gold>=500&&!state.animal.barn){state.gold-=500;state.animal.barn=true;say('Your farmhouse has a fresh new room!');}else say('Save 500g for a house expansion.');renderUI();save()}}
function openMine(){modal(`<div class="modal-head"><h2>Moonstone Hollow</h2><button class="close-btn" data-close>×</button></div><div class="modal-body"><p>Cool air breathes from the old mine. The stone walls hum faintly, as if holding a distant memory.</p><div class="quest-card"><div class="quest-top"><span class="quest-name">The Valley’s Hidden Heart</span><span class="quest-tag">STORY</span></div><p>Gather 5 moonstone ore and bring it to Lina in the village. She may know what the old mine is trying to say.</p><div class="objective">MOONSTONE ORE · ${state.inventory.Ore||0} / 5</div></div>${state.inventory.Ore>=5?'<button class="action-button" id="deliverOre">Bring the ore to Lina</button>':'<p>Equip your pickaxe and strike the exposed stone to gather ore.</p>'}</div>`);bindModal();let d=document.getElementById('deliverOre');if(d)d.onclick=()=>{spendItem('Ore',5);state.story=2;state.friendship.Lina+=4;closeModal();say('Lina recognizes the old valley sigil. A new story begins…');save();renderUI()}}
function modal(html){modalOpen=true;let m=document.getElementById('modal');m.classList.remove('hidden');document.getElementById('modalCard').innerHTML=html;bindModal()}
function bindModal(){let b=document.querySelector('[data-close]');if(b)b.onclick=closeModal;document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')closeModal()}}
function closeModal(){modalOpen=false;document.getElementById('modal').classList.add('hidden')}

