function nextDay(){state.day++;state.time=360;state.energy=state.maxEnergy;state.season=Math.floor((state.day-1)/28)%4;state.year=1+Math.floor((state.day-1)/112);state.day=(state.day-1)%28+1;state.weather=Math.random()<.25?1:(Math.random()<.3?2:0);for(const [k,c] of Object.entries(state.crops)){if(state.watered[k]===state.day-1||state.weather===1)c.age++;}state.watered={};say(`A new day dawns. ${seasons[state.season]} Day ${state.day}.`);renderUI();save()}
function changeTool(n){state.tool=(n+tools.length)%tools.length;updateHud()}
function move(dt){if(modalOpen)return;let dx=0,dy=0;if(keys.ArrowUp||keys.w)dy=-1;if(keys.ArrowDown||keys.s)dy=1;if(keys.ArrowLeft||keys.a)dx=-1;if(keys.ArrowRight||keys.d)dx=1;if(dx&&dy){dx*=.707;dy*=.707}state.moving=!!(dx||dy);if(!state.moving)return;state.face=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');let speed=3.1*dt;if(!blocked(state.px+dx*speed,state.py))state.px+=dx*speed;if(!blocked(state.px,state.py+dy*speed))state.py+=dy*speed;state.time+=dt*2.7;if(state.time>=1320)nextDay();updateHud(false)}
function draw(){ctx.clearRect(0,0,640,400);let camX=Math.max(0,Math.min(W*T-640,state.px*T-320)),camY=Math.max(0,Math.min(H*T-400,state.py*T-200));let startX=Math.floor(camX/T),startY=Math.floor(camY/T),endX=Math.ceil((camX+640)/T),endY=Math.ceil((camY+400)/T);for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++)drawTile(x,y,x*T-camX,y*T-camY);let ents=[];for(let n of npcs)if(Math.abs(n.x*T-camX-320)<400&&Math.abs(n.y*T-camY-200)<280)ents.push({y:n.y,draw:()=>drawNPC(n,n.x*T-camX,n.y*T-camY)});for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++){let c=cropAt(x,y);if(c)ents.push({y:y+.7,draw:()=>drawCrop(x*T-camX,y*T-camY,c)})}ents.push({y:state.py,draw:()=>drawPlayer(state.px*T-camX,state.py*T-camY)});ents.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());drawLighting();}
function drawTile(x,y,px,py){let t=tile(x,y),r=seedHash(x,y);ctx.fillStyle=t==='water'?'#477e85':t==='shore'?'#b8aa78':t==='sand'?'#c5b77e':t==='rock'?'#565b50':t==='path'?'#a49369':t==='dirt'?'#8f704f':t==='house'?'#72543c':t==='fence'?'#8f714d':'#628350';ctx.fillRect(px,py,T,T);if(['grass','flower'].includes(t)){ctx.fillStyle=r>.5?'#71905a':'#5b7d4b';ctx.fillRect(px+((r*14)|0),py+((seedHash(x+4,y)*13)|0),2,2);if(r>.94){ctx.fillStyle='#e7d994';ctx.fillRect(px+10,py+5,2,2)}}else if(t==='water'||t==='shore'){ctx.fillStyle='#8ab2a0';let phase=(anim*.02+x+y)%9;ctx.fillRect(px+3+phase,py+5,4,1);ctx.fillRect(px+9-phase/2,py+11,3,1)}else if(t==='path'||t==='sand'){ctx.fillStyle='#d3c28e55';if(r>.3)ctx.fillRect(px+4,py+8,2,1);if(r>.6)ctx.fillRect(px+12,py+3,1,2)}else if(t==='dirt'){ctx.fillStyle='#a7865b';ctx.fillRect(px+2,py+4,12,1);ctx.fillRect(px+3,py+11,10,1);if(state.watered[cropKey(x,y)]===state.day){ctx.fillStyle='#536c4d';ctx.fillRect(px+1,py+1,14,14)}}else if(t==='fence'){ctx.fillStyle='#b59463';ctx.fillRect(px,py+5,16,3);ctx.fillRect(px,py+11,16,3);ctx.fillRect(px+3,py+2,3,13);ctx.fillRect(px+11,py+2,3,13)}else if(t==='tree')drawTree(px,py,r);else if(t==='rock'){ctx.fillStyle='#858779';ctx.fillRect(px+3,py+6,10,8);ctx.fillStyle='#b7b9a2';ctx.fillRect(px+5,py+4,6,6);ctx.fillStyle='#616958';ctx.fillRect(px+4,py+12,8,2)}else if(t==='house')drawHouse(px,py,x,y)}
