function modal(html){modalOpen=true;document.getElementById('modal').classList.remove('hidden');document.getElementById('modalCard').innerHTML=html;bindModal()}function bindModal(){let b=document.querySelector('[data-close]');if(b)b.onclick=closeModal;document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')closeModal()}}function closeModal(){modalOpen=false;document.getElementById('modal').classList.add('hidden')}
function nextDay(){state.day++;state.time=360;state.energy=state.maxEnergy;state.season=Math.floor((state.day-1)/28)%4;state.year=1+Math.floor((state.day-1)/112);state.day=(state.day-1)%28+1;state.weather=Math.random()<.25?1:(Math.random()<.3?2:0);for(const [k,c] of Object.entries(state.crops))if(state.watered[k]===state.day-1||state.weather===1)c.age++;state.watered={};say(`A new day dawns. ${seasons[state.season]} Day ${state.day}.`);renderUI();save()}
function changeTool(n){state.tool=(n+tools.length)%tools.length;updateHud()}
function move(dt){if(modalOpen)return;let dx=0,dy=0;if(keys.ArrowUp||keys.w)dy=-1;if(keys.ArrowDown||keys.s)dy=1;if(keys.ArrowLeft||keys.a)dx=-1;if(keys.ArrowRight||keys.d)dx=1;if(dx&&dy){dx*=.707;dy*=.707}state.moving=!!(dx||dy);if(!state.moving)return;state.face=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');let speed=3.1*dt;if(!blocked(state.px+dx*speed,state.py))state.px+=dx*speed;if(!blocked(state.px,state.py+dy*speed))state.py+=dy*speed;state.time+=dt*2.7;if(state.time>=1320)nextDay();updateHud(false)}
function draw(){ctx.clearRect(0,0,640,400);let camX=Math.max(0,Math.min(W*T-640,state.px*T-320)),camY=Math.max(0,Math.min(H*T-400,state.py*T-200)),startX=Math.floor(camX/T),startY=Math.floor(camY/T),endX=Math.ceil((camX+640)/T),endY=Math.ceil((camY+400)/T);for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++)drawTile(x,y,x*T-camX,y*T-camY);let ents=[];for(let n of npcs)if(Math.abs(n.x*T-camX-320)<400&&Math.abs(n.y*T-camY-200)<280)ents.push({y:n.y,draw:()=>drawNPC(n,n.x*T-camX,n.y*T-camY)});for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++){let c=cropAt(x,y);if(c)ents.push({y:y+.7,draw:()=>drawCrop(x*T-camX,y*T-camY,c)})}ents.push({y:state.py,draw:()=>drawPlayer(state.px*T-camX,state.py*T-camY)});ents.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());drawLighting()}
function drawTile(x,y,px,py){let t=tile(x,y),r=seedHash(x,y);ctx.fillStyle=t==='water'?'#477e85':t==='shore'?'#b8aa78':t==='sand'?'#c5b77e':t==='rock'?'#565b50':t==='path'?'#a49369':t==='dirt'?'#8f704f':t==='house'?'#72543c':t==='fence'?'#8f714d':'#628350';ctx.fillRect(px,py,T,T);if(['grass','flower'].includes(t)){ctx.fillStyle=r>.5?'#71905a':'#5b7d4b';ctx.fillRect(px+((r*14)|0),py+((seedHash(x+4,y)*13)|0),2,2);if(r>.94){ctx.fillStyle='#e7d994';ctx.fillRect(px+10,py+5,2,2)}}else if(t==='water'||t==='shore'){ctx.fillStyle='#8ab2a0';let phase=(anim*.02+x+y)%9;ctx.fillRect(px+3+phase,py+5,4,1);ctx.fillRect(px+9-phase/2,py+11,3,1)}else if(t==='path'||t==='sand'){ctx.fillStyle='#d3c28e55';if(r>.3)ctx.fillRect(px+4,py+8,2,1);if(r>.6)ctx.fillRect(px+12,py+3,1,2)}else if(t==='dirt'){ctx.fillStyle='#a7865b';ctx.fillRect(px+2,py+4,12,1);ctx.fillRect(px+3,py+11,10,1);if(state.watered[cropKey(x,y)]===state.day){ctx.fillStyle='#536c4d';ctx.fillRect(px+1,py+1,14,14)}}else if(t==='fence'){ctx.fillStyle='#b59463';ctx.fillRect(px,py+5,16,3);ctx.fillRect(px,py+11,16,3);ctx.fillRect(px+3,py+2,3,13);ctx.fillRect(px+11,py+2,3,13)}else if(t==='tree')drawTree(px,py,r);else if(t==='rock'){ctx.fillStyle='#858779';ctx.fillRect(px+3,py+6,10,8);ctx.fillStyle='#b7b9a2';ctx.fillRect(px+5,py+4,6,6);ctx.fillStyle='#616958';ctx.fillRect(px+4,py+12,8,2)}else if(t==='house')drawHouse(px,py,x,y)}
function drawTree(x,y,r){ctx.fillStyle='#563f31';ctx.fillRect(x+7,y+9,4,8);ctx.fillStyle=r>.5?'#34553b':'#3e6342';ctx.fillRect(x+3,y+4,10,9);ctx.fillRect(x+1,y+7,14,6);ctx.fillStyle='#55764a';ctx.fillRect(x+4,y+3,7,5);ctx.fillStyle='#78915a';ctx.fillRect(x+5,y+4,3,2);ctx.fillStyle='#283f31';ctx.fillRect(x+3,y+13,11,2)}
function drawHouse(x,y){ctx.fillStyle='#634332';ctx.fillRect(x+1,y+4,14,12);ctx.fillStyle='#9b6447';ctx.fillRect(x,y+3,16,4);ctx.fillStyle='#b27a50';ctx.fillRect(x+2,y,12,5);ctx.fillStyle='#d3b579';ctx.fillRect(x+4,y+8,3,3);ctx.fillRect(x+10,y+8,3,3);ctx.fillStyle='#46362d';ctx.fillRect(x+7,y+11,3,5)}
function drawCrop(x,y,c){let full=crops[c.type].days,green=Math.min(1,c.age/full);ctx.fillStyle='#344432';ctx.fillRect(x+5,y+11,6,2);ctx.fillStyle=c.age>=full?'#83a34f':'#6c9b57';let h=3+Math.round(green*7);ctx.fillRect(x+7,y+10-h,2,h);ctx.fillRect(x+4,y+7-h,4,3);ctx.fillRect(x+9,y+8-h,4,3);if(c.age>=full){ctx.fillStyle=c.type==='Turnip'?'#d7e5cd':c.type==='Carrot'?'#e49555':c.type==='Tomato'?'#cf6551':'#d28a3c';ctx.fillRect(x+5,y+4,6,5);ctx.fillStyle='#edf0d6';ctx.fillRect(x+6,y+5,2,2)}}
function drawNPC(n,x,y){ctx.fillStyle='#29352b';ctx.fillRect(x+3,y+12,10,3);ctx.fillStyle=n.name==='Mara'?'#6a9b70':n.name==='Theo'?'#617f95':'#ad7894';ctx.fillRect(x+4,y+5,8,9);ctx.fillStyle='#e9c39d';ctx.fillRect(x+5,y+1,7,6);ctx.fillStyle=n.name==='Mara'?'#644632':n.name==='Theo'?'#6b4c3b':'#403a52';ctx.fillRect(x+4,y,9,3);ctx.fillStyle='#f0ead4';ctx.fillRect(x+6,y+3,1,1);ctx.fillRect(x+10,y+3,1,1);ctx.fillStyle='#fff4d8';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText(n.name,x+8,y-3)}
function drawPlayer(x,y){let bob=state.moving?Math.sin(anim*.35)*1:0;ctx.fillStyle='#27362a';ctx.fillRect(x+3,y+12+bob,10,3);ctx.fillStyle='#456b63';ctx.fillRect(x+4,y+5+bob,8,8);ctx.fillStyle='#eac4a0';ctx.fillRect(x+5,y+1+bob,7,6);ctx.fillStyle='#735543';ctx.fillRect(x+4,y+bob,9,3);ctx.fillStyle='#fff2d6';let eye=state.face==='left'?5:state.face==='right'?11:9;ctx.fillRect(x+eye,y+3+bob,1,1);if(state.face==='down')ctx.fillRect(x+6,y+4+bob,1,1);ctx.fillStyle='#d4c17e';ctx.fillRect(x+4,y+12+bob,3,2);ctx.fillRect(x+9,y+12+bob,3,2)}
function drawLighting(){let t=state.time/60,a=t<6.5?.22:t<8?.10:t>18?.17:t>20?.30:0;if(a){ctx.fillStyle=state.weather===1?'#253c45':'#202f48';ctx.globalAlpha=a;ctx.fillRect(0,0,640,400);ctx.globalAlpha=1}}

