function updateHud(full=true){document.getElementById('energyText').textContent=`${Math.max(0,Math.floor(state.energy))} / ${state.maxEnergy}`;document.getElementById('energyFill').style.width=`${Math.max(0,state.energy/state.maxEnergy*100)}%`;document.getElementById('toolName').textContent=tools[state.tool].name;document.getElementById('timeLabel').textContent=clockText();document.getElementById('locationName').textContent=zone(Math.floor(state.px),Math.floor(state.py));if(full)renderUI()}
function renderUI(){document.getElementById('seasonLabel').textContent=`${seasons[state.season].toUpperCase()} · YEAR ${state.year}`;document.getElementById('dayLabel').textContent=`Day ${state.day}`;document.getElementById('goldLabel').textContent=state.gold;document.getElementById('timeLabel').textContent=clockText();let wi=document.getElementById('weatherIcon'),wt=document.getElementById('weatherText');wi.textContent=state.weather===1?'☂':state.weather===2?'☁':'☀';wt.textContent=state.weather===1?'Gentle rain':state.weather===2?'Cloudy':'Clear skies';let bar=document.getElementById('hotbar');bar.innerHTML=tools.map((t,i)=>`<button class="slot ${i===state.tool?'selected':''}" data-tool="${i}" title="${t.name}"><span class="slot-key">${i+1}</span><span class="slot-icon">${t.icon}</span></button>`).join('');bar.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>changeTool(+b.dataset.tool));updateHud(false);renderTab()}
function renderTab(){let c=document.getElementById('tabContent');document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===activeTab));if(activeTab==='journal'){let left=Math.max(0,5-(state.inventory.Ore||0));c.innerHTML=`<div class="section-title">A fresh start</div><div class="quest-card"><div class="quest-top"><span class="quest-name">The Valley’s Hidden Heart</span><span class="quest-tag">MAIN STORY</span></div><p>${state.story>=2?'Lina has begun to decipher the sigil. The valley’s old paths may hold the next clue.':'A faint blue glow pulses from Moonstone Hollow. Gather ore and ask Lina what she knows.'}</p><div class="progress-track"><i style="width:${state.story>=2?100:Math.min(100,(state.inventory.Ore||0)*20)}%"></i></div><div class="objective">MOONSTONE ORE · ${state.story>=2?'DELIVERED':`${state.inventory.Ore||0} / 5`}</div></div><div class="quest-card"><div class="quest-top"><span class="quest-name">First Harvest</span><span class="quest-tag">FARMING</span></div><p>Plant seeds in the tilled patch, water them, then harvest when they’re ready.</p><div class="objective">CROPS HARVESTED · ${state.quests.turnips}</div></div><div class="mini-heading">TODAY IN THE VALLEY</div><div class="weather-note"><b>${state.weather===1?'Rain is watering the valley':state.weather===2?'A quiet, cloudy day':'A bright day to begin'}</b><br>${state.weather===1?'Your crops will grow without a visit from the watering can.':'Mara’s seed cart is open in Fernhollow Village.'}</div><div class="mini-heading">QUICK BAG</div><div class="objective">SEEDS ${state.inventory['Turnip Seeds']+state.inventory['Carrot Seeds']} · WOOD ${state.inventory.Wood} · STONE ${state.inventory.Stone} · ORE ${state.inventory.Ore}</div>`}else if(activeTab==='people'){c.innerHTML=`<div class="section-title">Folks around here</div>${npcs.map(n=>`<div class="people-row"><div class="portrait">${n.icon}</div><div class="person-info"><b>${n.name}</b><span>${n.role}</span></div><div class="heart-meter">${'♥'.repeat(Math.min(5,Math.ceil((state.friendship[n.name]||0)/2)))}${'♡'.repeat(5-Math.min(5,Math.ceil((state.friendship[n.name]||0)/2)))}</div></div>`).join('')}<div class="mini-heading">A SMALL KINDNESS GOES FAR</div><div class="weather-note">Talk to someone each day, and share a flower, fish, or harvest to grow closer.</div>`}else{c.innerHTML=`<div class="section-title">Little things to make</div><div class="craft-item"><span class="craft-icon">📦</span><div class="craft-copy"><b>Storage chest</b><span>12 wood · 4 stone</span></div><button id="craftChest" ${state.inventory.Wood>=12&&state.inventory.Stone>=4?'':'disabled'}>MAKE</button></div><div class="craft-item"><span class="craft-icon">🪵</span><div class="craft-copy"><b>Wood fence · 6</b><span>3 wood · garden decor</span></div><button id="craftFence" ${state.inventory.Wood>=3?'':'disabled'}>MAKE</button></div><div class="craft-item"><span class="craft-icon">🐔</span><div class="craft-copy"><b>Small chicken coop</b><span>100 wood · 40 stone · 300g</span></div><button id="craftCoop" ${state.inventory.Wood>=100&&state.inventory.Stone>=40&&state.gold>=300?'':'disabled'}>${state.animal.coop?'BUILT':'MAKE'}</button></div><div class="weather-note">Crafted chests can be placed with the bag menu. Decor and animal shelters help make the farm your own.</div>`;let chest=document.getElementById('craftChest');if(chest)chest.onclick=()=>{spendItem('Wood',12);spendItem('Stone',4);state.chests.push({x:Math.floor(state.px)+1,y:Math.floor(state.py)});say('A storage chest is ready on your farm.');renderUI();save()};let fence=document.getElementById('craftFence');if(fence)fence.onclick=()=>{spendItem('Wood',3);addItem('Wood Fence',6);say('Six wooden fence pieces made.');renderUI()};let coop=document.getElementById('craftCoop');if(coop)coop.onclick=()=>{spendItem('Wood',100);spendItem('Stone',40);state.gold-=300;state.animal.coop=true;say('Your chicken coop is ready! Eggs will arrive each morning.');renderUI();save()}}
}
function openInventory(){let entries=Object.entries(state.inventory).filter(([,n])=>n>0);modal(`<div class="modal-head"><h2>Your satchel</h2><button class="close-btn" data-close>×</button></div><div class="modal-body">A small collection of things from your days in the valley.<div class="inventory-grid">${entries.map(([name,count])=>`<div class="inventory-cell"><i>${itemIcon(name)}</i><b>${name} ×${count}</b></div>`).join('')||'<p>Your bag is empty.</p>'}</div><div class="modal-buttons"><button id="sellHarvest">Sell harvest · ${state.inventory.Turnip*42+state.inventory.Carrot*65+state.inventory.Carp*26+state.inventory.Sunfish*40}g</button><button class="secondary" id="calendarFromBag">Calendar & events</button></div></div>`);bindModal();document.getElementById('sellHarvest').onclick=()=>{let earned=state.inventory.Turnip*42+state.inventory.Carrot*65+state.inventory.Carp*26+state.inventory.Sunfish*40;if(!earned){say('No harvest or fish to sell yet.');return}for(let a of ['Turnip','Carrot','Carp','Sunfish'])state.inventory[a]=0;state.gold+=earned;closeModal();say(`Sold your goods for ${earned}g.`);renderUI();save()};document.getElementById('calendarFromBag').onclick=openCalendar}
function itemIcon(n){return ({'Turnip Seeds':'🌱','Carrot Seeds':'🌱','Tomato Seeds':'🌱','Pumpkin Seeds':'🌱',Turnip:'🫜',Carrot:'🥕',Tomato:'🍅',Pumpkin:'🎃',Wood:'🪵',Stone:'🪨',Ore:'✨',Fiber:'🌿',Wildflower:'🌼',Carp:'🐟',Sunfish:'🐠',Milk:'🥛',Egg:'🥚',Fish:'🐟','Wood Fence':'🪵'})[n]||'✦'}
function openCalendar(){modal(`<div class="modal-head"><h2>Valley calendar</h2><button class="close-btn" data-close>×</button></div><div class="modal-body"><div class="section-title">${seasons[state.season]} · Year ${state.year}</div><div class="inventory-grid">${Array.from({length:28},(_,i)=>`<div class="inventory-cell" style="min-height:42px;background:${i+1===state.day?'#536347':''}"><b>${i+1}</b>${i+1===14?'<small> ✿</small>':''}</div>`).join('')}</div><div class="weather-note"><b>Day 14 · Lanternbloom Gathering</b><br>Meet everyone in the village square when the sun is high. Bring something grown with care.</div><p>The valley keeps its own gentle time. Each season lasts 28 days.</p></div>`);bindModal()}
function save(){try{localStorage.setItem('hearthwild-save',JSON.stringify(state));document.getElementById('saveStatus').textContent='Saved just now';setTimeout(()=>{let e=document.getElementById('saveStatus');if(e)e.textContent='All progress saved locally'},1400)}catch(e){}}
function load(){try{let raw=localStorage.getItem('hearthwild-save');if(raw){let old=JSON.parse(raw);Object.assign(state,old);state.inventory=Object.assign({},state.inventory,old.inventory||{});state.crops=old.crops||{};state.tilled=old.tilled||{};state.watered=old.watered||{};state.friendship=Object.assign(state.friendship,old.friendship||{});return true}}catch(e){}return false}
function frame(ts){let dt=Math.min(.05,(ts-lastTime)/1000||0);lastTime=ts;anim+=dt*60;move(dt);draw();requestAnimationFrame(frame)}
function bind(){window.addEventListener('keydown',e=>{let k=e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();keys[k]=true;if(modalOpen){if(k==='Escape')closeModal();return}if(k===' '){useTool()}else if(k.toLowerCase()==='e'||k==='Enter')interact();else if(k.toLowerCase()==='i')openInventory();else if(k==='Escape')openInventory();else if(k>='1'&&k<='4')changeTool(+k-1);else if(k==='Tab'){e.preventDefault();activeTab=activeTab==='journal'?'people':activeTab==='people'?'craft':'journal';renderTab()}});window.addEventListener('keyup',e=>keys[e.key]=false);document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;renderTab()});document.getElementById('calendarBtn').onclick=openCalendar;document.getElementById('saveBtn').onclick=()=>{save();say('Your valley is safely tucked away.')};document.getElementById('soundBtn').onclick=()=>say('The valley hums softly in the breeze.');document.getElementById('mobileAction').onclick=useTool;document.querySelectorAll('[data-move]').forEach(b=>{let k={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[b.dataset.move];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});canvas.addEventListener('pointerdown',()=>canvas.focus())}
const hadSave=load();bind();renderUI();updateHud();if(!hadSave)say('Welcome to Mosslight Farm. The valley is yours to discover.');requestAnimationFrame(frame);
})();

