function move(dt){if(modalOpen)return;let dx=0,dy=0;if(keys.ArrowUp||keys.w)dy=-1;if(keys.ArrowDown||keys.s)dy=1;if(keys.ArrowLeft||keys.a)dx=-1;if(keys.ArrowRight||keys.d)dx=1;if(dx&&dy){dx*=.707;dy*=.707}state.moving=!!(dx||dy);if(!state.moving)return;state.face=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');let speed=3.1*dt;if(!blocked(state.px+dx*speed,state.py))state.px+=dx*speed;if(!blocked(state.px,state.py+dy*speed))state.py+=dy*speed;state.time+=dt*2.7;if(state.time>=1320)nextDay();updateHud(false)}
function draw(){ctx.clearRect(0,0,640,400);let camX=Math.max(0,Math.min(W*T-640,state.px*T-320)),camY=Math.max(0,Math.min(H*T-400,state.py*T-200)),startX=Math.floor(camX/T),startY=Math.floor(camY/T),endX=Math.ceil((camX+640)/T),endY=Math.ceil((camY+400)/T);for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++)drawTile(x,y,x*T-camX,y*T-camY);let ents=[];for(let n of npcs)if(Math.abs(n.x*T-camX-320)<400&&Math.abs(n.y*T-camY-200)<280)ents.push({y:n.y,draw:()=>drawNPC(n,n.x*T-camX,n.y*T-camY)});for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++){let c=cropAt(x,y);if(c)ents.push({y:y+.7,draw:()=>drawCrop(x*T-camX,y*T-camY,c)})}for(let c of state.chests||[])ents.push({y:c.y+.7,draw:()=>drawChest(c.x*T-camX,c.y*T-camY)});for(let f of state.fences||[])ents.push({y:f.y+.7,draw:()=>drawFence(f.x*T-camX,f.y*T-camY)});ents.push({y:state.py,draw:()=>drawPlayer(state.px*T-camX,state.py*T-camY)});ents.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());drawLighting()}
function drawTile(x,y,px,py){let t=tile(x,y),r=seedHash(x,y);ctx.fillStyle=t==='water'?'#477e85':t==='shore'?'#b8aa78':t==='sand'?'#c5b77e':t==='rock'||t==='minefloor'||t==='oreRock'?'#565b50':t==='path'?'#a49369':t==='dirt'?'#8f704f':t==='house'?'#72543c':t==='fence'?'#8f714d':'#628350';ctx.fillRect(px,py,T,T);if(['grass','flower'].includes(t)){ctx.fillStyle=r>.5?'#71905a':'#5b7d4b';ctx.fillRect(px+((r*14)|0),py+((seedHash(x+4,y)*13)|0),2,2);if(r>.94){ctx.fillStyle='#e7d994';ctx.fillRect(px+10,py+5,2,2)}}else if(t==='water'||t==='shore'){ctx.fillStyle='#8ab2a0';let phase=(anim*.02+x+y)%9;ctx.fillRect(px+3+phase,py+5,4,1);ctx.fillRect(px+9-phase/2,py+11,3,1)}else if(t==='path'||t==='sand'){ctx.fillStyle='#d3c28e55';if(r>.3)ctx.fillRect(px+4,py+8,2,1);if(r>.6)ctx.fillRect(px+12,py+3,1,2)}else if(t==='dirt'){ctx.fillStyle='#a7865b';ctx.fillRect(px+2,py+4,12,1);ctx.fillRect(px+3,py+11,10,1);if(state.watered[cropKey(x,y)]===state.day){ctx.fillStyle='#536c4d';ctx.fillRect(px+1,py+1,14,14)}}else if(t==='fence'){ctx.fillStyle='#b59463';ctx.fillRect(px,py+5,16,3);ctx.fillRect(px,py+11,16,3);ctx.fillRect(px+3,py+2,3,13);ctx.fillRect(px+11,py+2,3,13)}else if(t==='tree')drawTree(px,py,r);else if(t==='rock'||t==='oreRock'){ctx.fillStyle=t==='oreRock'?'#797c70':'#858779';ctx.fillRect(px+3,py+6,10,8);ctx.fillStyle=t==='oreRock'?'#96a37d':'#b7b9a2';ctx.fillRect(px+5,py+4,6,6);ctx.fillStyle=t==='oreRock'?'#d3c27b':'#616958';ctx.fillRect(px+4,py+12,8,2)}else if(t==='minefloor'){ctx.fillStyle='#717568';ctx.fillRect(px+4,py+5,2,1);ctx.fillRect(px+11,py+12,3,1)}else if(t==='house')drawHouse(px,py,x,y)}
function drawTree(x,y,r){ctx.fillStyle='#563f31';ctx.fillRect(x+7,y+9,4,8);ctx.fillStyle=r>.5?'#34553b':'#3e6342';ctx.fillRect(x+3,y+4,10,9);ctx.fillRect(x+1,y+7,14,6);ctx.fillStyle='#55764a';ctx.fillRect(x+4,y+3,7,5);ctx.fillStyle='#78915a';ctx.fillRect(x+5,y+4,3,2);ctx.fillStyle='#283f31';ctx.fillRect(x+3,y+13,11,2)}
function drawHouse(x,y){ctx.fillStyle='#634332';ctx.fillRect(x+1,y+4,14,12);ctx.fillStyle='#9b6447';ctx.fillRect(x,y+3,16,4);ctx.fillStyle='#b27a50';ctx.fillRect(x+2,y,12,5);ctx.fillStyle='#d3b579';ctx.fillRect(x+4,y+8,3,3);ctx.fillRect(x+10,y+8,3,3);ctx.fillStyle='#46362d';ctx.fillRect(x+7,y+11,3,5)}
function drawCrop(x,y,c){let full=crops[c.type].days,green=Math.min(1,c.age/full);ctx.fillStyle='#344432';ctx.fillRect(x+5,y+11,6,2);ctx.fillStyle=c.age>=full?'#83a34f':'#6c9b57';let h=3+Math.round(green*7);ctx.fillRect(x+7,y+10-h,2,h);ctx.fillRect(x+4,y+7-h,4,3);ctx.fillRect(x+9,y+8-h,4,3);if(c.age>=full){ctx.fillStyle=c.type==='Turnip'?'#d7e5cd':c.type==='Carrot'?'#e49555':c.type==='Tomato'?'#cf6551':'#d28a3c';ctx.fillRect(x+5,y+4,6,5);ctx.fillStyle='#edf0d6';ctx.fillRect(x+6,y+5,2,2)}}
function drawNPC(n,x,y){ctx.fillStyle='#29352b';ctx.fillRect(x+3,y+12,10,3);ctx.fillStyle=n.name==='Mara'?'#6a9b70':n.name==='Theo'?'#617f95':'#ad7894';ctx.fillRect(x+4,y+5,8,9);ctx.fillStyle='#e9c39d';ctx.fillRect(x+5,y+1,7,6);ctx.fillStyle=n.name==='Mara'?'#644632':n.name==='Theo'?'#6b4c3b':'#403a52';ctx.fillRect(x+4,y,9,3);ctx.fillStyle='#f0ead4';ctx.fillRect(x+6,y+3,1,1);ctx.fillRect(x+10,y+3,1,1);ctx.fillStyle='#fff4d8';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText(n.name,x+8,y-3)}
function drawPlayer(x,y){let bob=state.moving?Math.sin(anim*.35)*1:0;ctx.fillStyle='#27362a';ctx.fillRect(x+3,y+12+bob,10,3);ctx.fillStyle='#456b63';ctx.fillRect(x+4,y+5+bob,8,8);ctx.fillStyle='#eac4a0';ctx.fillRect(x+5,y+1+bob,7,6);ctx.fillStyle='#735543';ctx.fillRect(x+4,y+bob,9,3);ctx.fillStyle='#fff2d6';let eye=state.face==='left'?5:state.face==='right'?11:9;ctx.fillRect(x+eye,y+3+bob,1,1);if(state.face==='down')ctx.fillRect(x+6,y+4+bob,1,1);ctx.fillStyle='#d4c17e';ctx.fillRect(x+4,y+12+bob,3,2);ctx.fillRect(x+9,y+12+bob,3,2)}
function drawChest(x,y){ctx.fillStyle='#65422d';ctx.fillRect(x+2,y+5,12,8);ctx.fillStyle='#9b7548';ctx.fillRect(x+3,y+3,10,3);ctx.fillStyle='#d1b66f';ctx.fillRect(x+7,y+7,3,3);ctx.fillStyle='#46372d';ctx.fillRect(x+2,y+12,12,2)}function drawFence(x,y){ctx.fillStyle='#b59463';ctx.fillRect(x,y+5,16,3);ctx.fillRect(x,y+11,16,3);ctx.fillRect(x+3,y+2,3,13);ctx.fillRect(x+11,y+2,3,13)}
function drawLighting(){let t=state.time/60,a=t<6.5?.22:t<8?.10:t>18?.17:t>20?.30:0;if(a){ctx.fillStyle=state.weather===1?'#253c45':'#202f48';ctx.globalAlpha=a;ctx.fillRect(0,0,640,400);ctx.globalAlpha=1}}
function clockText(){let hr=Math.floor(state.time/60),min=Math.floor(state.time%60/10)*10,ap=hr>=12?'PM':'AM';hr=hr%12||12;return `${hr}:${String(min).padStart(2,'0')} ${ap}`}
function updateHud(full=true){document.getElementById('energyText').textContent=`${Math.max(0,Math.floor(state.energy))} / ${state.maxEnergy}`;document.getElementById('energyFill').style.width=`${Math.max(0,state.energy/state.maxEnergy*100)}%`;document.getElementById('toolName').textContent=tools[state.tool].name;document.getElementById('timeLabel').textContent=clockText();document.getElementById('locationName').textContent=zone(Math.floor(state.px),Math.floor(state.py));if(full)renderUI()}
function renderUI(){document.getElementById('seasonLabel').textContent=`${seasons[state.season].toUpperCase()} · YEAR ${state.year}`;document.getElementById('dayLabel').textContent=`Day ${state.day}`;document.getElementById('goldLabel').textContent=state.gold;document.getElementById('timeLabel').textContent=clockText();let wi=document.getElementById('weatherIcon'),wt=document.getElementById('weatherText');wi.textContent=state.weather===1?'☂':state.weather===2?'☁':'☀';wt.textContent=state.weather===1?'Gentle rain':state.weather===2?'Cloudy':'Clear skies';let bar=document.getElementById('hotbar');bar.innerHTML=tools.map((t,i)=>`<button class="slot ${i===state.tool?'selected':''}" data-tool="${i}" title="${t.name}"><span class="slot-key">${i+1}</span><span class="slot-icon">${t.icon}</span></button>`).join('');bar.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>changeTool(+b.dataset.tool));updateHud(false);renderTab()}
function renderTab(){let c=document.getElementById('tabContent');document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===activeTab));if(activeTab==='journal'){let left=Math.max(0,5-(state.inventory.Ore||0));c.innerHTML=`<div class="section-title">A fresh start</div><div class="quest-card"><div class="quest-top"><span class="quest-name">The Valley’s Hidden Heart</span><span class="quest-tag">MAIN STORY</span></div><p>${state.story>=2?'Lina has begun to decipher the sigil. The valley’s old paths may hold the next clue.':'A faint blue glow pulses from Moonstone Hollow. Gather ore and ask Lina what she knows.'}</p><div class="progress-track"><i style="width:${state.story>=2?100:Math.min(100,(state.inventory.Ore||0)*20)}%"></i></div><div class="objective">MOONSTONE ORE · ${state.story>=2?'DELIVERED':`${state.inventory.Ore||0} / 5`}</div></div><div class="quest-card"><div class="quest-top"><span class="quest-name">First Harvest</span><span class="quest-tag">FARMING</span></div><p>Plant seeds in the tilled patch, water them, then harvest when they’re ready.</p><div class="objective">CROPS HARVESTED · ${state.quests.turnips}</div></div><div class="mini-heading">TODAY IN THE VALLEY</div><div class="weather-note"><b>${state.weather===1?'Rain is watering the valley':state.weather===2?'A quiet, cloudy day':'A bright day to begin'}</b><br>${state.weather===1?'Your crops will grow without a visit from the watering can.':'Mara’s seed cart is open in Fernhollow Village.'}</div><div class="mini-heading">QUICK BAG</div><div class="objective">SEEDS ${state.inventory['Turnip Seeds']+state.inventory['Carrot Seeds']} · WOOD ${state.inventory.Wood} · STONE ${state.inventory.Stone} · ORE ${state.inventory.Ore}</div>`}else if(activeTab==='people'){c.innerHTML=`<div class="section-title">Folks around here</div>${npcs.map(n=>`<div class="people-row"><div class="portrait">${n.icon}</div><div class="person-info"><b>${n.name}</b><span>${n.role}</span></div><div class="heart-meter">${'♥'.repeat(Math.min(5,Math.ceil((state.friendship[n.name]||0)/2)))}${'♡'.repeat(5-Math.min(5,Math.ceil((state.friendship[n.name]||0)/2)))}</div></div>`).join('')}<div class="mini-heading">A SMALL KINDNESS GOES FAR</div><div class="weather-note">Talk to someone each day, and share a flower, fish, or harvest to grow closer.</div>`}else{c.innerHTML=`<div class="section-title">Little things to make</div><div class="craft-item"><span class="craft-icon">📦</span><div class="craft-copy"><b>Storage chest</b><span>12 wood · 4 stone</span></div><button id="craftChest" ${state.inventory.Wood>=12&&state.inventory.Stone>=4?'':'disabled'}>MAKE</button></div><div class="craft-item"><span class="craft-icon">🪵</span><div class="craft-copy"><b>Wood fence · 6</b><span>3 wood · garden decor</span></div><button id="craftFence" ${state.inventory.Wood>=3?'':'disabled'}>MAKE</button></div><div class="craft-item"><span class="craft-icon">🐔</span><div class="craft-copy"><b>Small chicken coop</b><span>100 wood · 40 stone · 300g</span></div><button id="craftCoop" ${state.inventory.Wood>=100&&state.inventory.Stone>=40&&state.gold>=300?'':'disabled'}>${state.animal.coop?'BUILT':'MAKE'}</button></div><div class="weather-note">Crafted chests can be placed with the bag menu. Decor and animal shelters help make the farm your own.</div>`;let chest=document.getElementById('craftChest');if(chest)chest.onclick=()=>{spendItem('Wood',12);spendItem('Stone',4);addItem('Chest',1);say('A storage chest kit is ready. Place it from your bag.');renderUI();save()};let fence=document.getElementById('craftFence');if(fence)fence.onclick=()=>{spendItem('Wood',3);addItem('Wood Fence',6);say('Six wooden fence pieces made.');renderUI();save()};let coop=document.getElementById('craftCoop');if(coop)coop.onclick=()=>{spendItem('Wood',100);spendItem('Stone',40);state.gold-=300;state.animal.coop=true;say('Your chicken coop is ready! Eggs will arrive each morning.');renderUI();save()}}
}
function placeKit(type){let [x,y]=facingTile();if(['water','tree','house','rock','oreRock','fence'].includes(tile(x,y))||cropAt(x,y)||npcs.some(n=>n.x===x&&n.y===y)||state.chests.some(c=>c.x===x&&c.y===y)||state.fences.some(f=>f.x===x&&f.y===y)){say('There isn’t clear ground to place that here.');return}if(type==='chest'){if(!spendItem('Chest'))return;state.chests.push({x,y,items:{}});say('Chest placed. Interact with it to store finds.')}else{if(!spendItem('Wood Fence'))return;state.fences.push({x,y});say('Fence piece placed.')}closeModal();renderUI();save()}
function openChest(chest){chest.items=chest.items||{};let stored=Object.entries(chest.items).filter(([,n])=>n>0);let bagged=Object.entries(state.inventory).filter(([n,v])=>v>0&&!n.includes('Seeds')&&n!=='Chest'&&n!=='Wood Fence');modal(`<div class="modal-head"><h2>Farm chest</h2><button class="close-btn" data-close>×</button></div><div class="modal-body"><p>Store the useful things you find.</p><div class="inventory-grid">${stored.map(([n,v])=>`<div class="inventory-cell"><i>${itemIcon(n)}</i><b>${n} ×${v}</b></div>`).join('')||'<p>The chest is empty.</p>'}</div><div class="modal-buttons"><button id="depositChest">Deposit materials</button><button id="withdrawChest">Withdraw stored items</button></div></div>`);bindModal();document.getElementById('depositChest').onclick=()=>{for(let [n,v] of bagged){if(['Wood','Stone','Ore','Fiber','Wildflower','Carp','Sunfish','Milk','Egg','Fish','Turnip','Carrot','Tomato','Pumpkin'].includes(n)){chest.items[n]=(chest.items[n]||0)+v;state.inventory[n]=0}}closeModal();say('Useful finds stored in the chest.');renderUI();save()};document.getElementById('withdrawChest').onclick=()=>{for(let [n,v] of stored){addItem(n,v)}chest.items={};closeModal();say('Stored items returned to your bag.');renderUI();save()}}
function openInventory(){let entries=Object.entries(state.inventory).filter(([,n])=>n>0);modal(`<div class="modal-head"><h2>Your satchel</h2><button class="close-btn" data-close>×</button></div><div class="modal-body">A small collection of things from your days in the valley.<div class="inventory-grid">${entries.map(([name,count])=>`<div class="inventory-cell"><i>${itemIcon(name)}</i><b>${name} ×${count}</b></div>`).join('')||'<p>Your bag is empty.</p>'}</div><div class="modal-buttons"><button id="sellHarvest">Sell harvest · ${state.inventory.Turnip*42+state.inventory.Carrot*65+state.inventory.Tomato*95+state.inventory.Pumpkin*160+state.inventory.Carp*26+state.inventory.Sunfish*40+state.inventory.Egg*35}g</button>${state.inventory.Chest?' <button id="placeChest">Place chest</button>':''}${state.inventory['Wood Fence']?' <button id="placeFence">Place fence</button>':''}<button class="secondary" id="calendarFromBag">Calendar & events</button></div></div>`);bindModal();document.getElementById('sellHarvest').onclick=()=>{let earned=state.inventory.Turnip*42+state.inventory.Carrot*65+state.inventory.Tomato*95+state.inventory.Pumpkin*160+state.inventory.Carp*26+state.inventory.Sunfish*40+state.inventory.Egg*35;if(!earned){say('No harvest or fish to sell yet.');return}for(let a of ['Turnip','Carrot','Tomato','Pumpkin','Carp','Sunfish','Egg'])state.inventory[a]=0;state.gold+=earned;closeModal();say(`Sold your goods for ${earned}g.`);renderUI();save()};document.getElementById('calendarFromBag').onclick=openCalendar;let pc=document.getElementById('placeChest');if(pc)pc.onclick=()=>placeKit('chest');let pf=document.getElementById('placeFence');if(pf)pf.onclick=()=>placeKit('fence')}
function itemIcon(n){return ({Chest:'📦','Turnip Seeds':'🌱','Carrot Seeds':'🌱','Tomato Seeds':'🌱','Pumpkin Seeds':'🌱',Turnip:'🫜',Carrot:'🥕',Tomato:'🍅',Pumpkin:'🎃',Wood:'🪵',Stone:'🪨',Ore:'✨',Fiber:'🌿',Wildflower:'🌼',Carp:'🐟',Sunfish:'🐠',Milk:'🥛',Egg:'🥚',Fish:'🐟','Wood Fence':'🪵'})[n]||'✦'}
function openCalendar(){modal(`<div class="modal-head"><h2>Valley calendar</h2><button class="close-btn" data-close>×</button></div><div class="modal-body"><div class="section-title">${seasons[state.season]} · Year ${state.year}</div><div class="inventory-grid">${Array.from({length:28},(_,i)=>`<div class="inventory-cell" style="min-height:42px;background:${i+1===state.day?'#536347':''}"><b>${i+1}</b>${i+1===14?'<small> ✿</small>':''}</div>`).join('')}</div><div class="weather-note"><b>Day 14 · Lanternbloom Gathering</b><br>Meet everyone in the village square when the sun is high. Bring something grown with care.</div><p>The valley keeps its own gentle time. Each season lasts 28 days.</p></div>`);bindModal()}
function save(){try{localStorage.setItem('hearthwild-save',JSON.stringify(state));document.getElementById('saveStatus').textContent='Saved just now';setTimeout(()=>{let e=document.getElementById('saveStatus');if(e)e.textContent='All progress saved locally'},1400)}catch(e){}}
function load(){try{let raw=localStorage.getItem('hearthwild-save');if(raw){let old=JSON.parse(raw);Object.assign(state,old);state.inventory=Object.assign({},state.inventory,old.inventory||{});state.crops=old.crops||{};state.tilled=old.tilled||{};state.watered=old.watered||{};state.chests=Array.isArray(old.chests)?old.chests:[];state.fences=Array.isArray(old.fences)?old.fences:[];state.friendship=Object.assign(state.friendship,old.friendship||{});return true}}catch(e){}return false}
function frame(ts){let dt=Math.min(.05,(ts-lastTime)/1000||0);lastTime=ts;anim+=dt*60;move(dt);draw();requestAnimationFrame(frame)}
function bind(){window.addEventListener('keydown',e=>{let k=e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();keys[k]=true;if(modalOpen){if(k==='Escape')closeModal();return}if(k===' '){useTool()}else if(k.toLowerCase()==='e'||k==='Enter')interact();else if(k.toLowerCase()==='i')openInventory();else if(k==='Escape')openInventory();else if(k>='1'&&k<='4')changeTool(+k-1);else if(k==='Tab'){e.preventDefault();activeTab=activeTab==='journal'?'people':activeTab==='people'?'craft':'journal';renderTab()}});window.addEventListener('keyup',e=>keys[e.key]=false);document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;renderTab()});document.getElementById('calendarBtn').onclick=openCalendar;document.getElementById('saveBtn').onclick=()=>{save();say('Your valley is safely tucked away.')};document.getElementById('soundBtn').onclick=()=>say('The valley hums softly in the breeze.');document.getElementById('mobileAction').onclick=interact;document.querySelectorAll('[data-move]').forEach(b=>{let k={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[b.dataset.move];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});canvas.addEventListener('pointerdown',()=>canvas.focus())}
const hadSave=load();bind();renderUI();updateHud();if(!hadSave)say('Welcome to Mosslight Farm. The valley is yours to discover.');requestAnimationFrame(frame);
