Index: game.js
===================================================================
--- game.js
+++ game.js
@@ -17,9 +17,9 @@
 if(state.tool===2){if(t==='tree'){addItem('Wood',3);state.energy-=4;say('You gathered 3 wood.')}else if(t==='flower'){addItem('Fiber',1);state.energy-=2;say('A little fiber for crafting.')}else{say('There is nothing to chop here.');return}}
 if(state.tool===3){if(t==='rock'||t==='oreRock'||zone(x,y)==='Moonstone Mine'){ addItem('Stone',2);if(zone(x,y)==='Moonstone Mine'||Math.random()<.35)addItem('Ore',1);state.energy-=4;say('You mined a small deposit.')}else{say('No stone within reach.');return}}updateHud()}
 function interact(){if(modalOpen){closeModal();return}let [x,y]=facingTile(),chest=state.chests?.find(c=>c.x===x&&c.y===y);if(chest){openChest(chest);return}let fence=state.fences?.find(f=>f.x===x&&f.y===y);if(fence){say('A neatly placed wooden fence.');return}let n=npcs.find(p=>Math.abs(p.x-x)<2&&Math.abs(p.y-y)<2);if(n){talk(n);return}let z=zone(x,y);if(z==='Moonstone Mine'){openMine();return}if(z==='Glasswater Beach'){say('Glasswater shimmers in the late light. Cast a line with your watering can.');return}if(tile(x,y)==='house'||(state.px>21&&state.px<26&&state.py>15&&state.py<19)){openHouse();return}if(tile(x,y)==='dirt'&&cropAt(x,y)){let c=cropAt(x,y),def=crops[c.type];if(c.age>=def.days){delete state.crops[cropKey(x,y)];delete state.tilled[cropKey(x,y)];addItem(c.type);state.quests.turnips++;say(`Harvested ${c.type}!`);return}say(`${c.type} · ${Math.max(0,def.days-c.age)} day(s) to harvest`);return}if(z==='Fernhollow Village'){openMarket();return}say('The valley is quiet. Try the village path to meet someone.')}
 function fishing(){let z=zone(...facingTile());if(!['Glasswater Beach','Moonstone Mine'].includes(z)&&tile(...facingTile())!=='water'){say('Find a river or the sea to fish.');return}if(state.energy<8){say('You need a little more energy to fish.');return}state.energy-=8;let kind=Math.random(),fish=kind>.7?'Sunfish':'Carp';addItem(fish);say(`A ${fish} bites! You reel it in.`);updateHud()}
-function talk(n){let f=state.friendship[n.name]||0;modal(`<div class="dialogue-name">${n.name.toUpperCase()} · ${n.role}</div><div class="dialogue-text">${f===0?`“Oh, hello! You must be the new farmer. I’m ${n.name}. The valley feels a little brighter with someone new around.”`:f<3?`“Good to see you again. ${n.story}`:`“I’m glad you found your way here. I have a feeling this valley has more to tell us yet.”`}</div><div class="choice-row"><button data-choice="chat">Ask about the valley</button><button data-choice="gift">Offer a gift</button><button data-choice="bye">Say goodbye</button></div>`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='chat'){state.friendship[n.name]=Math.min(10,f+1);state.story=Math.max(state.story,1);closeModal();say(`${n.name} smiles. Friendship +1 ♡`);renderUI();save()}else if(b.dataset.choice==='gift')gift(n);else closeModal()})}
+function talk(n){let f=state.friendship[n.name]||0;let delivery=n.name==='Lina'&&state.story<2&&(state.inventory.Ore||0)>=5;modal(`<div class="dialogue-name">${n.name.toUpperCase()} · ${n.role}</div><div class="dialogue-text">${f===0?`“Oh, hello! You must be the new farmer. I’m ${n.name}. The valley feels a little brighter with someone new around.”`:f<3?`“Good to see you again. ${n.story}`:`“I’m glad you found your way here. I have a feeling this valley has more to tell us yet.”`}</div><div class="choice-row"><button data-choice="chat">Ask about the valley</button><button data-choice="gift">Offer a gift</button>${delivery?' <button data-choice="deliver">Give 5 moonstone ore</button>':''}<button data-choice="bye">Say goodbye</button></div>`);bindModal();document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='chat'){state.friendship[n.name]=Math.min(10,f+1);state.story=Math.max(state.story,1);closeModal();say(`${n.name} smiles. Friendship +1 ♡`);renderUI();save()}else if(b.dataset.choice==='gift')gift(n);else if(b.dataset.choice==='deliver')deliverOreToLina(n);else closeModal()})}
 function deliverOreToLina(n){if(n.name!=='Lina'||(state.inventory.Ore||0)<5){say('You need 5 moonstone ore for Lina.');return}spendItem('Ore',5);state.story=2;state.friendship.Lina=Math.min(10,(state.friendship.Lina||0)+4);closeModal();say('Lina studies the ore and smiles. A new story begins…');save();renderUI()}
 function gift(n){let item=Object.keys(state.inventory).find(k=>state.inventory[k]>0&&['Wildflower','Turnip','Carrot','Carp','Sunfish','Milk','Egg'].includes(k));if(!item){say('You do not have a gift to share yet.');return}spendItem(item);state.friendship[n.name]=Math.min(10,(state.friendship[n.name]||0)+2);closeModal();say(`${n.name} loves your ${item.toLowerCase()}! Friendship +2 ♡`);renderUI();save()}
 function openMarket(){modal(`<div class="modal-head"><h2>Mara’s seed cart</h2><button class="close-btn" data-close>×</button></div><div class="modal-body">Fresh seeds for the new season. Pick something to grow in your little patch.</div><div class="craft-item"><span class="craft-icon">🫜</span><div class="craft-copy"><b>Turnip Seeds</b><span>Spring · 3 days · 20g</span></div><button data-buy="Turnip Seeds" data-cost="20">BUY</button></div><div class="craft-item"><span class="craft-icon">🥕</span><div class="craft-copy"><b>Carrot Seeds</b><span>Spring · 4 days · 32g</span></div><button data-buy="Carrot Seeds" data-cost="32">BUY</button></div><div class="craft-item"><span class="craft-icon">🍅</span><div class="craft-copy"><b>Tomato Seeds</b><span>Summer · 5 days · 48g</span></div><button data-buy="Tomato Seeds" data-cost="48">BUY</button></div>`);bindModal();document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let cost=+b.dataset.cost;if(state.gold<cost){say('Not enough gold yet.');return}state.gold-=cost;addItem(b.dataset.buy);say(`${b.dataset.buy} added to your bag.`);renderUI();save()})}
 function openHouse(){modal(`<div class="modal-head"><h2>Your little farmhouse</h2><button class="close-btn" data-close>×</button></div><div class="modal-body"><p>The old windows catch the last of the afternoon sun. It’s simple, but it’s yours.</p><div class="quest-card"><div class="quest-top"><span class="quest-name">A Place to Begin</span><span class="quest-tag">HOME</span></div><p>Home is where a new story takes root. Rest here to welcome the next morning.</p></div><button class="action-button" id="sleepBtn">Rest until morning</button> <button class="action-button" id="upgradeBtn">House upgrade · 500g</button><p>Craft a chest from 12 wood and 4 stone to store your finds.</p></div>`);bindModal();document.getElementById('sleepBtn').onclick=()=>{closeModal();nextDay()};document.getElementById('upgradeBtn').onclick=()=>{if(state.gold>=500&&!state.animal.barn){state.gold-=500;state.animal.barn=true;say('Your farmhouse has a fresh new room!')}else say('Save 500g for a house expansion.');renderUI();save()}}

